#!/usr/bin/env python3
"""Sixty-first patch layer: the texts added by the ports and the long option descriptions are translated into the eight other languages (de es fr it pt nl tr hi), and the option
descriptions now go through the translator like everything else (they used to stay English; the Language option said so, and no longer does). Rows are only added for texts that
have none yet. Not translated on purpose: names of apps, inputs, the TV's own picture and sound mode names, wallpaper titles (they are the photographers' own captions)."""
import os, json
APP = os.path.expanduser('~/Developer/webos-launcher-tvos/app')
def P(p): return os.path.join(APP, p)
def sub(p, pairs):
    s = open(P(p)).read()
    for a, b in pairs:
        assert s.count(a) == 1, (p, s.count(a), a[:90])
        s = s.replace(a, b, 1)
    open(P(p), 'w').write(s)

# the descriptions: the Settings pages show them next to the list (and per choice)
sub('src/screens/Settings.tsx', [("list.map((o) => o.description)", "list.map((o) => tr(o.description))"), ("o.choices.map(() => o.description)", "o.choices.map(() => tr(o.description))")])
if "{o.description}" in open(P('src/components/OptionList.tsx')).read():
    sub('src/components/OptionList.tsx', [("{o.description}", "{tr(o.description)}")])
sub('src/app.tsx', [(" The long descriptions on this screen stay in English.", "")])

# order: de, es, fr, it, pt, nl, tr, hi
